import { chmodSync, existsSync, lstatSync, mkdirSync, readdirSync, readFileSync, realpathSync, renameSync, rmSync, writeFileSync, accessSync, constants } from 'fs'
import { homedir } from 'os'
import { delimiter, join } from 'path'
import type { ConfigLayers } from './config'

/** Marks files generated by `mx-env shell-init`; handmade files lack it and are never touched. */
export const SHIM_MARKER = '# mx-env shim — regenerated by `mx-env shell-init`; do not edit by hand.'

/**
 * Names a shim may never take: every CLI subcommand, both bin names, and the
 * internal editor entry. Kept in one place; test/shims.test.ts asserts parity
 * with the dispatch table in cli.ts so future commands cannot drift past it.
 */
export const RESERVED_SHIM_NAMES = [
  'run', 'fetch', 'export', 'render', 'inject', 'generate', 'gen',
  'inspect', 'migrate', 'audit', 'edit', 'doc', 'skill', 'shell-init', 'help',
  'mx-env', 'morphix-env', '__mx_editor',
]

const SHIM_NAME_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/

export function shimsDir(homeDir = homedir()): string {
  return join(homeDir, '.mx-env', 'shims')
}

/**
 * Validates one declared shim list. Command names are configuration, not
 * secrets, so echoing the offending entry is safe. Callers decide the blast
 * radius: shell-init hard-fails, composition paths warn and ignore (a
 * convenience layer must never become a single point of failure for run).
 */
export function validateShimList(list: unknown, label: string): string[] {
  if (list === undefined || list === null) return []
  if (!Array.isArray(list)) return [`${label}: "shims" must be an array of command names`]
  const errors: string[] = []
  const seen = new Set<string>()
  for (const entry of list) {
    if (typeof entry !== 'string' || !entry) {
      errors.push(`${label}: shim entries must be non-empty command names`)
      continue
    }
    if (!SHIM_NAME_PATTERN.test(entry)) {
      errors.push(`${label}: shim entry "${entry}" must be a bare command name (letters, digits, ".", "_", "-"; no path separators or whitespace)`)
      continue
    }
    const lower = entry.toLowerCase()
    if (RESERVED_SHIM_NAMES.includes(lower)) {
      errors.push(`${label}: shim entry "${entry}" conflicts with a reserved mx-env command name`)
      continue
    }
    if (seen.has(lower)) {
      errors.push(`${label}: duplicate shim entry "${entry}" (comparison is case-insensitive)`)
      continue
    }
    seen.add(lower)
  }
  return errors
}

/** Effective shim list: global ∪ project, deduplicated case-insensitively. */
export function resolveShimCommands(layers: ConfigLayers, includeGlobal = true): string[] {
  const seen = new Set<string>()
  const commands: string[] = []
  const push = (list: unknown) => {
    if (!Array.isArray(list)) return
    for (const entry of list) {
      if (typeof entry !== 'string') continue
      const lower = entry.toLowerCase()
      if (seen.has(lower)) continue
      seen.add(lower)
      commands.push(entry)
    }
  }
  if (includeGlobal) push(layers.global.config.shims)
  push(layers.project.config.shims)
  return commands
}

/**
 * Shim body: guard against a missing mx-env (uninstall, nvm switch) with an
 * actionable message instead of a bare "command not found", then hand off to
 * `run`. The marker line identifies tool-generated shims for --remove and
 * convergence; MXENV_SHIM is read by the CLI at boot and stripped before any
 * composition or child spawn.
 */
export function renderShimScript(command: string): string {
  return `#!/bin/sh
${SHIM_MARKER}
command -v mx-env >/dev/null 2>&1 || { echo "[mx-env] mx-env not on PATH; reinstall morphix-env or run 'mx-env shell-init --remove' to clean up this shim." >&2; exit 127; }
MXENV_SHIM=1 exec mx-env run -- ${command} "$@"
`
}

function readIfExists(path: string): string | null {
  try {
    return readFileSync(path, 'utf8')
  } catch {
    return null
  }
}

/**
 * Writes shims for the declared commands and converges the directory: stale
 * tool-generated shims (marker present) whose command is no longer declared
 * are removed. **Handmade files (no marker) are never touched** — a declared
 * command colliding with one is skipped and reported, never overwritten.
 * Idempotent — rewriting an up-to-date shim is skipped byte-for-byte.
 */
export function writeShims(commands: string[], homeDir = homedir()): { written: string[]; removed: string[]; skipped: string[] } {
  const dir = shimsDir(homeDir)
  mkdirSync(dir, { recursive: true, mode: 0o700 })
  const wanted = new Set(commands.map((command) => command.toLowerCase()))
  const written: string[] = []
  const removed: string[] = []
  const skipped: string[] = []

  for (const file of readdirSync(dir)) {
    const path = join(dir, file)
    const content = readIfExists(path)
    if (content === null || !content.includes(SHIM_MARKER)) continue
    if (!wanted.has(file.toLowerCase())) {
      rmSync(path)
      removed.push(file)
    }
  }
  for (const command of commands) {
    const path = join(dir, command)
    const content = renderShimScript(command)
    // Never follow a pre-existing symlink: reading/writing through it would
    // touch its target. Replace the link with a regular file instead.
    let isSymlink = false
    try {
      isSymlink = lstatSync(path).isSymbolicLink()
    } catch { /* absent */ }
    const existing = isSymlink ? null : readIfExists(path)
    if (!isSymlink && existing !== null && !existing.includes(SHIM_MARKER)) {
      // A handmade file holds the name. Refuse to overwrite; surface it.
      skipped.push(command)
      continue
    }
    if (isSymlink) rmSync(path)
    else if (existing === content) continue
    writeFileSync(path, content, { mode: 0o755 })
    chmodSync(path, 0o755)
    written.push(command)
  }
  return { written, removed, skipped }
}

/** Removes every tool-generated shim; handmade files are left alone. */
export function removeAllShims(homeDir = homedir()): string[] {
  const dir = shimsDir(homeDir)
  if (!existsSync(dir)) return []
  const removed: string[] = []
  for (const file of readdirSync(dir)) {
    const path = join(dir, file)
    const content = readIfExists(path)
    if (content !== null && content.includes(SHIM_MARKER)) {
      rmSync(path)
      removed.push(file)
    }
  }
  return removed
}

/**
 * Handmade files that shadow reserved mx-env names would wrap mx-env itself in
 * a shim (weird but terminating) — surface them so the user can delete them.
 */
export function detectHandmadeReservedShims(homeDir = homedir()): string[] {
  const dir = shimsDir(homeDir)
  if (!existsSync(dir)) return []
  const found: string[] = []
  for (const file of readdirSync(dir)) {
    if (!RESERVED_SHIM_NAMES.includes(file.toLowerCase())) continue
    const content = readIfExists(join(dir, file))
    if (content === null || !content.includes(SHIM_MARKER)) found.push(file)
  }
  return found
}

export const RC_BLOCK_BEGIN = '# >>> mx-env shims >>>'
export const RC_BLOCK_END = '# <<< mx-env shims <<<'

export function rcBlock(homeDir = homedir()): string {
  const dir = shimsDir(homeDir)
  // The path lands inside a double-quoted shell line; refuse characters that
  // could break out of it. Real $HOME values essentially never contain these.
  if (/["$`\\]/.test(dir)) {
    throw new Error('[morphix-env] Shims directory path contains characters that are unsafe in a shell rc line.')
  }
  return `${RC_BLOCK_BEGIN}\nexport PATH="${dir}:$PATH"\n${RC_BLOCK_END}`
}

/** Infers the rc file from $SHELL; returns null for shells we do not write. */
export function defaultRcPath(shell: string | undefined, homeDir = homedir()): string | null {
  const name = shell ? shell.split('/').pop() : ''
  if (name === 'zsh') return join(homeDir, '.zshrc')
  if (name === 'bash') return join(homeDir, '.bashrc')
  return null
}

/** Atomic write (tmp + rename) so a crash can never truncate a user's rc file. */
function writeFileAtomic(path: string, content: string): void {
  const tmp = `${path}.mx-env-${process.pid}.tmp`
  writeFileSync(tmp, content)
  renameSync(tmp, path)
}

/** Idempotently installs the PATH block; all existing marked blocks are replaced. */
export function upsertRcBlock(rcPath: string, homeDir = homedir()): 'added' | 'updated' | 'unchanged' {
  const existing = readIfExists(rcPath) ?? ''
  const block = rcBlock(homeDir)
  const pattern = new RegExp(`${escapeRegExp(RC_BLOCK_BEGIN)}[\\s\\S]*?${escapeRegExp(RC_BLOCK_END)}`, 'g')
  if (pattern.test(existing)) {
    const replaced = existing.replace(pattern, block)
    if (replaced === existing) return 'unchanged'
    writeFileAtomic(rcPath, replaced.endsWith('\n') ? replaced : `${replaced}\n`)
    return 'updated'
  }
  const separator = existing.length && !existing.endsWith('\n') ? '\n' : ''
  writeFileAtomic(rcPath, `${existing}${separator}${block}\n`)
  return 'added'
}

/** Idempotently removes every marked PATH block, leaving other content intact. */
export function removeRcBlock(rcPath: string): 'removed' | 'absent' {
  const existing = readIfExists(rcPath)
  if (existing === null) return 'absent'
  const pattern = new RegExp(`\\n?${escapeRegExp(RC_BLOCK_BEGIN)}[\\s\\S]*?${escapeRegExp(RC_BLOCK_END)}\\n?`, 'g')
  if (!pattern.test(existing)) return 'absent'
  writeFileAtomic(rcPath, existing.replace(pattern, '\n'))
  return 'removed'
}

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/**
 * Removes every PATH entry that resolves to the shims directory (filter-all,
 * so rc files that add it twice are both cleaned). Entries are compared after
 * realpath normalization on both sides, case-insensitively on macOS (whose
 * default filesystem would resolve `Run` to the `run` shim file).
 */
export function stripShimsFromPath(pathValue: string | undefined, homeDir = homedir()): string | undefined {
  if (!pathValue) return pathValue
  const target = shimsDir(homeDir)
  let targetReal = target
  try {
    targetReal = realpathSync(target)
  } catch { /* directory may not exist yet; literal comparison still applies */ }
  const equal = (a: string, b: string) =>
    process.platform === 'darwin' ? a.toLowerCase() === b.toLowerCase() : a === b
  const entries = pathValue.split(delimiter).filter((entry) => {
    if (!entry) return true
    const literal = entry.replace(/\/+$/, '')
    let resolved = literal
    try {
      resolved = realpathSync(literal)
    } catch { /* keep literal */ }
    return !equal(literal, target) && !equal(resolved, targetReal)
  })
  return entries.join(delimiter)
}

/**
 * Boot-time sanitization for every CLI command, not just `run`: composition
 * spawns provider subprocesses (doppler, plugins, dotenvx) that inherit PATH,
 * so a shimmed provider CLI would recurse shim → run → provider → shim.
 * Sanitizing process.env before any composition keeps the whole process tree
 * clean. Returns the pre-sanitization PATH (shell-init's parity check needs
 * the real one) and whether the invocation came through a shim.
 */
export function sanitizeBootEnv(env: NodeJS.ProcessEnv = process.env, homeDir?: string): { viaShim: boolean; originalPath?: string } {
  const originalPath = env.PATH
  const viaShim = env.MXENV_SHIM === '1'
  try {
    // homedir() can throw in hardened containers with no $HOME and no passwd
    // entry; light commands (--help/--version) must survive that.
    const home = homeDir ?? homedir()
    const stripped = stripShimsFromPath(originalPath, home)
    if (stripped !== originalPath) {
      if (stripped) env.PATH = stripped
      else delete env.PATH
    }
  } catch { /* sanitization is best-effort; composition paths resolve home themselves */ }
  delete env.MXENV_SHIM
  return { viaShim, originalPath }
}

/**
 * Per-command PATH parity: a declared command must resolve to its shim file.
 * `absent` — no executable by that name anywhere on PATH (first install: the
 * shims dir is not on PATH yet); `shadowed` — an earlier PATH entry (volta,
 * another tool) wins and the shim silently never fires. Uses the
 * pre-sanitization PATH captured at boot.
 */
export function findShadowedCommands(commands: string[], originalPath: string | undefined, homeDir = homedir()): { absent: string[]; shadowed: string[] } {
  if (!originalPath) return { absent: [...commands], shadowed: [] }
  const dirs = originalPath.split(delimiter).filter(Boolean)
  const absent: string[] = []
  const shadowed: string[] = []
  for (const command of commands) {
    const shimPath = join(shimsDir(homeDir), command)
    let resolvedTo: string | null = null
    for (const dir of dirs) {
      const candidate = join(dir, command)
      try {
        accessSync(candidate, constants.X_OK)
        resolvedTo = candidate
        break
      } catch { /* not here */ }
    }
    const samePath = (a: string, b: string) =>
      process.platform === 'darwin' ? a.toLowerCase() === b.toLowerCase() : a === b
    if (resolvedTo === null) absent.push(command)
    else if (!samePath(resolvedTo, shimPath)) shadowed.push(command)
  }
  return { absent, shadowed }
}
